1365→+// ValidateID checks if a string is a valid trail ID format.
1366→+func ValidateID(s string) error {
1367→+	if !idRegex.MatchString(s) {
1368→+		return fmt.Errorf("invalid trail ID %q: must be 12 lowercase hex characters", s)
1369→+	}
1370→+	return nil
