1383→+// Path returns the sharded storage path for this trail ID.
1384→+// Uses first 2 characters as shard (256 buckets), remaining as folder name.
1385→+// Example: "a3b2c4d5e6f7" -> "a3/b2c4d5e6f7"
1386→+func (id ID) Path() string {
