1488→+// HumanizeBranchName converts a branch name into a human-readable title.
1489→+// It strips common prefixes (feature/, fix/, etc.), replaces dashes/underscores
1490→+// with spaces, and capitalizes the first word.
1491→+func HumanizeBranchName(branch string) string {
1492→+	name := branch
1493→+	for _, prefix := range commonBranchPrefixes {
1494→+		if strings.HasPrefix(name, prefix) {
1495→+			name = strings.TrimPrefix(name, prefix)
1496→+			break
1497→+		}
1498→+	}
1499→+
1500→+	// Replace - and _ with spaces
1501→+	name = strings.NewReplacer("-", " ", "_", " ").Replace(name)
1502→+
1503→+	// Trim spaces and capitalize first letter
1504→+	name = strings.TrimSpace(name)
1505→+	if name == "" {
1506→+		return branch
1507→+	}
1508→+
1509→+	// Capitalize first character
1510→+	return strings.ToUpper(name[:1]) + name[1:]
1511→+}
