1802→+func runTrailListAll(w io.Writer, statusFilter string, jsonOutput bool) error {
1803→+	// Fetch remote trails branch so we see trails from collaborators
1804→+	fetchTrailsBranch()
1805→+
1806→+	repo, err := strategy.OpenRepository(context.Background())
1807→+	if err != nil {
1808→+		return fmt.Errorf("failed to open repository: %w", err)
1809→+	}
1810→+
1811→+	store := trail.NewStore(repo)
1812→+	trails, err := store.List()
1813→+	if err != nil {
1814→+		return fmt.Errorf("failed to list trails: %w", err)
1815→+	}
1816→+
1817→+	if trails == nil {
1818→+		trails = []*trail.Metadata{}
1819→+	}
1820→+
1821→+	// Apply status filter
1822→+	if statusFilter != "" {
1823→+		status := trail.Status(statusFilter)
1824→+		if !status.IsValid() {
1825→+			return fmt.Errorf("invalid status %q: valid values are %s", statusFilter, formatValidStatuses())
1826→+		}
1827→+		var filtered []*trail.Metadata
1828→+		for _, t := range trails {
1829→+			if t.Status == status {
1830→+				filtered = append(filtered, t)
1831→+			}
1832→+		}
1833→+		trails = filtered
1834→+	}
1835→+
1836→+	// Sort by updated_at descending
1837→+	sort.Slice(trails, func(i, j int) bool {
1838→+		return trails[i].UpdatedAt.After(trails[j].UpdatedAt)
1839→+	})
1840→+
1841→+	if jsonOutput {
1842→+		enc := json.NewEncoder(w)
1843→+		enc.SetIndent("", "  ")
1844→+		if err := enc.Encode(trails); err != nil {
1845→+			return fmt.Errorf("failed to encode JSON: %w", err)
1846→+		}
1847→+		return nil
1848→+	}
1849→+
1850→+	if len(trails) == 0 {
1851→+		fmt.Fprintln(w, "No trails found.")
1852→+		fmt.Fprintln(w)
1853→+		fmt.Fprintln(w, "Commands:")
1854→+		fmt.Fprintln(w, "  entire trail create   Create a trail for the current branch")
1855→+		fmt.Fprintln(w, "  entire trail list     List all trails")
1856→+		fmt.Fprintln(w, "  entire trail update   Update trail metadata")
1857→+		return nil
1858→+	}
1859→+
1860→+	// Table output
1861→+	fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n", "BRANCH", "TITLE", "STATUS", "AUTHOR", "UPDATED")
1862→+	for _, t := range trails {
1863→+		branch := truncate(t.Branch, 30)
1864→+		title := truncate(t.Title, 40)
1865→+		fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n",
1866→+			branch, title, t.Status, truncate(t.Author, 15), timeAgo(t.UpdatedAt))
1867→+	}
1868→+
1869→+	return nil
1870→+}
