1895→+func runTrailCreate(w, errW io.Writer, title, body, base, branch, statusStr string, checkout bool) error {
1896→+	repo, err := strategy.OpenRepository(context.Background())
1897→+	if err != nil {
1898→+		return fmt.Errorf("failed to open repository: %w", err)
1899→+	}
1900→+
1901→+	// Determine base branch
1902→+	if base == "" {
1903→+		base = strategy.GetDefaultBranchName(repo)
1904→+		if base == "" {
1905→+			base = defaultBaseBranch
1906→+		}
1907→+	}
1908→+
1909→+	_, currentBranch, _ := IsOnDefaultBranch(context.Background()) //nolint:errcheck // best-effort detection
1910→+	interactive := !hasFlag("title") && !hasFlag("branch")
1911→+
1912→+	if interactive {
1913→+		// Interactive flow: title → body → branch (derived) → status
1914→+		if err := runTrailCreateInteractive(&title, &body, &branch, &statusStr); err != nil {
1915→+			return err
1916→+		}
1917→+	} else {
1918→+		// Non-interactive: derive missing values from provided flags
1919→+		if branch == "" {
1920→+			if hasFlag("title") {
1921→+				branch = slugifyTitle(title)
1922→+			} else {
1923→+				branch = currentBranch
1924→+			}
1925→+		}
1926→+		if title == "" {
1927→+			title = trail.HumanizeBranchName(branch)
1928→+		}
1929→+	}
1930→+	if branch == "" {
1931→+		return errors.New("branch name is required")
1932→+	}
1933→+
1934→+	// Create the branch if it doesn't exist
1935→+	needsCreation := branchNeedsCreation(repo, branch)
1936→+	if needsCreation {
1937→+		if err := createBranch(repo, branch); err != nil {
1938→+			return fmt.Errorf("failed to create branch %q: %w", branch, err)
1939→+		}
1940→+		fmt.Fprintf(w, "Created branch %s\n", branch)
1941→+	} else if currentBranch != branch {
1942→+		fmt.Fprintf(errW, "Note: trail will be created for branch %q (not the current branch)\n", branch)
1943→+	}
1944→+
1945→+	// Check if trail already exists for this branch
1946→+	store := trail.NewStore(repo)
1947→+	existing, err := store.FindByBranch(branch)
1948→+	if err == nil && existing != nil {
1949→+		fmt.Fprintf(w, "Trail already exists for branch %q (ID: %s)\n", branch, existing.TrailID)
1950→+		return nil
1951→+	}
1952→+
1953→+	// Determine status
1954→+	var trailStatus trail.Status
1955→+	if statusStr != "" {
1956→+		trailStatus = trail.Status(statusStr)
1957→+		if !trailStatus.IsValid() {
1958→+			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
1959→+		}
1960→+	} else {
1961→+		trailStatus = trail.StatusDraft
1962→+	}
1963→+
1964→+	// Generate trail ID
1965→+	trailID, err := trail.GenerateID()
1966→+	if err != nil {
1967→+		return fmt.Errorf("failed to generate trail ID: %w", err)
1968→+	}
1969→+
1970→+	// Get author (GitHub username, falls back to git user.name)
1971→+	authorName := getTrailAuthor(repo)
1972→+
1973→+	now := time.Now()
1974→+	metadata := &trail.Metadata{
1975→+		TrailID:   trailID,
1976→+		Branch:    branch,
1977→+		Base:      base,
1978→+		Title:     title,
1979→+		Body:      body,
1980→+		Status:    trailStatus,
1981→+		Author:    authorName,
1982→+		Assignees: []string{},
1983→+		Labels:    []string{},
1984→+		CreatedAt: now,
1985→+		UpdatedAt: now,
1986→+	}
1987→+
1988→+	if err := store.Write(metadata, nil, nil); err != nil {
1989→+		return fmt.Errorf("failed to create trail: %w", err)
1990→+	}
1991→+
1992→+	fmt.Fprintf(w, "Created trail %q for branch %s (ID: %s)\n", title, branch, trailID)
1993→+
1994→+	// Push the branch and trail data to origin
1995→+	if needsCreation {
1996→+		if err := pushBranchToOrigin(branch); err != nil {
1997→+			fmt.Fprintf(errW, "Warning: failed to push branch: %v\n", err)
1998→+		} else {
1999→+			fmt.Fprintf(w, "Pushed branch %s to origin\n", branch)
2000→+		}
2001→+	}
2002→+	if err := strategy.PushTrailsBranch(context.Background(), "origin"); err != nil {
2003→+		fmt.Fprintf(errW, "Warning: failed to push trail data: %v\n", err)
2004→+	}
2005→+
2006→+	// Checkout the branch if requested or prompted
2007→+	if needsCreation && currentBranch != branch {
2008→+		shouldCheckout := checkout
2009→+		if !shouldCheckout && !hasFlag("checkout") {
2010→+			// Interactive: ask whether to checkout
2011→+			form := NewAccessibleForm(
2012→+				huh.NewGroup(
2013→+					huh.NewConfirm().
2014→+						Title(fmt.Sprintf("Check out branch %s?", branch)).
2015→+						Value(&shouldCheckout),
2016→+				),
2017→+			)
2018→+			if formErr := form.Run(); formErr == nil && shouldCheckout {
2019→+				checkout = true
2020→+			}
2021→+		}
2022→+		if checkout {
2023→+			if err := CheckoutBranch(context.Background(), branch); err != nil {
2024→+				return fmt.Errorf("failed to checkout branch %q: %w", branch, err)
2025→+			}
2026→+			fmt.Fprintf(w, "Switched to branch %s\n", branch)
2027→+		}
2028→+	}
