2055→+func runTrailUpdate(w io.Writer, statusStr, title, body, branch string, labelAdd, labelRemove []string) error {
2056→+	repo, err := strategy.OpenRepository(context.Background())
2057→+	if err != nil {
2058→+		return fmt.Errorf("failed to open repository: %w", err)
2059→+	}
2060→+
2061→+	// Determine branch
2062→+	if branch == "" {
2063→+		branch, err = GetCurrentBranch(context.Background())
2064→+		if err != nil {
2065→+			return fmt.Errorf("failed to determine current branch: %w", err)
2066→+		}
2067→+	}
2068→+
2069→+	store := trail.NewStore(repo)
2070→+	metadata, err := store.FindByBranch(branch)
2071→+	if err != nil {
2072→+		return fmt.Errorf("failed to find trail: %w", err)
2073→+	}
2074→+	if metadata == nil {
2075→+		return fmt.Errorf("no trail found for branch %q", branch)
2076→+	}
2077→+
2078→+	// Interactive mode when no flags are provided
2079→+	noFlags := statusStr == "" && title == "" && body == "" && labelAdd == nil && labelRemove == nil
2080→+	if noFlags {
2081→+		// Build status options with current value as default.
2082→+		// Exclude "done" and "closed" unless the trail is already in that status
2083→+		// (otherwise the select would silently reset to the first option).
2084→+		var statusOptions []huh.Option[string]
2085→+		for _, s := range trail.ValidStatuses() {
2086→+			if (s == trail.StatusDone || s == trail.StatusClosed) && s != metadata.Status {
2087→+				continue
2088→+			}
2089→+			label := string(s)
2090→+			if s == metadata.Status {
2091→+				label += " (current)"
2092→+			}
2093→+			statusOptions = append(statusOptions, huh.NewOption(label, string(s)))
2094→+		}
2095→+		statusStr = string(metadata.Status)
2096→+		title = metadata.Title
2097→+		body = metadata.Body
2098→+
2099→+		form := NewAccessibleForm(
2100→+			huh.NewGroup(
2101→+				huh.NewSelect[string]().
2102→+					Title("Status").
2103→+					Options(statusOptions...).
2104→+					Value(&statusStr),
2105→+				huh.NewInput().
2106→+					Title("Title").
2107→+					Value(&title),
2108→+				huh.NewText().
2109→+					Title("Body").
2110→+					Value(&body),
2111→+			),
2112→+		)
2113→+		if formErr := form.Run(); formErr != nil {
2114→+			return fmt.Errorf("form cancelled: %w", formErr)
2115→+		}
2116→+	}
2117→+
2118→+	// Validate status if provided
2119→+	if statusStr != "" {
2120→+		status := trail.Status(statusStr)
2121→+		if !status.IsValid() {
2122→+			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
2123→+		}
2124→+	}
2125→+
2126→+	err = store.Update(metadata.TrailID, func(m *trail.Metadata) {
2127→+		if statusStr != "" {
2128→+			m.Status = trail.Status(statusStr)
2129→+		}
2130→+		if title != "" {
2131→+			m.Title = title
2132→+		}
2133→+		if body != "" {
2134→+			m.Body = body
2135→+		}
2136→+		for _, l := range labelAdd {
2137→+			if !containsString(m.Labels, l) {
2138→+				m.Labels = append(m.Labels, l)
2139→+			}
2140→+		}
2141→+		for _, l := range labelRemove {
2142→+			m.Labels = removeString(m.Labels, l)
2143→+		}
2144→+	})
2145→+	if err != nil {
2146→+		return fmt.Errorf("failed to update trail: %w", err)
2147→+	}
2148→+
2149→+	fmt.Fprintf(w, "Updated trail for branch %s\n", branch)
2150→+	return nil
2151→+}
