2158→+func hasFlag(name string) bool {
2159→+	for _, arg := range os.Args {
2160→+		if arg == "--"+name || strings.HasPrefix(arg, "--"+name+"=") {
2161→+			return true
2162→+		}
2163→+	}
2164→+	return false
2165→+}
