2167→+func truncate(s string, maxLen int) string {
2168→+	if len(s) <= maxLen {
2169→+		return s
2170→+	}
2171→+	if maxLen <= 3 {
2172→+		return s[:maxLen]
2173→+	}
2174→+	return s[:maxLen-3] + "..."
2175→+}
