2177→+func formatValidStatuses() string {
2178→+	statuses := trail.ValidStatuses()
2179→+	names := make([]string, len(statuses))
2180→+	for i, s := range statuses {
2181→+		names[i] = string(s)
2182→+	}
2183→+	return strings.Join(names, ", ")
