2185→+
2186→+func containsString(slice []string, s string) bool {
2187→+	for _, v := range slice {
2188→+		if v == s {
2189→+			return true
2190→+		}
2191→+	}
2192→+	return false
2193→+}
2194→+
2195→+func removeString(slice []string, s string) []string {
2196→+	var result []string
2197→+	for _, v := range slice {
2198→+		if v != s {
2199→+			result = append(result, v)
2200→+		}
2201→+	}
2202→+	return result
2203→+}
