2205→+// runTrailCreateInteractive runs the interactive form for trail creation.
2206→+// Prompts for title, body, branch (derived from title), and status.
2207→+func runTrailCreateInteractive(title, body, branch, statusStr *string) error {
2208→+	// Step 1: Title and body
2209→+	form := NewAccessibleForm(
2210→+		huh.NewGroup(
2211→+			huh.NewInput().
2212→+				Title("Trail title").
2213→+				Placeholder("What are you working on?").
2214→+				Value(title),
2215→+			huh.NewText().
2216→+				Title("Body (optional)").
2217→+				Value(body),
2218→+		),
2219→+	)
2220→+	if err := form.Run(); err != nil {
2221→+		return fmt.Errorf("form cancelled: %w", err)
2222→+	}
2223→+	*title = strings.TrimSpace(*title)
2224→+	if *title == "" {
2225→+		return errors.New("trail title is required")
2226→+	}
2227→+
2228→+	// Step 2: Branch (derived from title) and status
2229→+	suggested := slugifyTitle(*title)
2230→+	*branch = suggested
2231→+
2232→+	// Build status options, excluding done/closed
2233→+	var statusOptions []huh.Option[string]
2234→+	for _, s := range trail.ValidStatuses() {
2235→+		if s == trail.StatusDone || s == trail.StatusClosed {
2236→+			continue
2237→+		}
2238→+		statusOptions = append(statusOptions, huh.NewOption(string(s), string(s)))
2239→+	}
2240→+	if *statusStr == "" {
2241→+		*statusStr = string(trail.StatusDraft)
2242→+	}
2243→+
2244→+	form = NewAccessibleForm(
2245→+		huh.NewGroup(
2246→+			huh.NewInput().
2247→+				Title("Branch name").
2248→+				Placeholder(suggested).
2249→+				Value(branch),
2250→+			huh.NewSelect[string]().
2251→+				Title("Status").
2252→+				Options(statusOptions...).
2253→+				Value(statusStr),
2254→+		),
2255→+	)
2256→+	if err := form.Run(); err != nil {
2257→+		return fmt.Errorf("form cancelled: %w", err)
2258→+	}
2259→+	*branch = strings.TrimSpace(*branch)
2260→+	if *branch == "" {
2261→+		*branch = suggested
2262→+	}
2263→+	return nil
2264→+}
