2266→+// fetchTrailsBranch fetches the remote trails branch so we see trails from collaborators.
2267→+// Best-effort: silently ignores errors (e.g., no remote, no network).
2268→+func fetchTrailsBranch() {
2269→+	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
2270→+	defer cancel()
2271→+	branchName := paths.TrailsBranchName
2272→+	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
2273→+
2274→+	cmd := exec.CommandContext(ctx, "git", "fetch", "origin", refSpec)
2275→+	// Ensure non-interactive fetch in hook/agent contexts
2276→+	cmd.Stdin = nil
2277→+	cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0")
2278→+	_ = cmd.Run() //nolint:errcheck // best-effort fetch
2279→+}
