2281→+// getTrailAuthor returns the GitHub username for the trail author.
2282→+// Falls back to git user.name if gh CLI is unavailable or not authenticated.
2283→+func getTrailAuthor(repo *git.Repository) string {
2284→+	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
2285→+	defer cancel()
2286→+	cmd := exec.CommandContext(ctx, "gh", "api", "user", "-q", ".login")
2287→+	if output, err := cmd.Output(); err == nil {
2288→+		if login := strings.TrimSpace(string(output)); login != "" {
2289→+			return login
2290→+		}
2291→+	}
2292→+	name, _ := strategy.GetGitAuthorFromRepo(repo)
2293→+	return name
2294→+}
