2296→+// slugifyTitle converts a title string into a branch-friendly slug.
2297→+// Example: "Add user authentication" -> "add-user-authentication"
2298→+func slugifyTitle(title string) string {
2299→+	s := strings.ToLower(strings.TrimSpace(title))
2300→+	// Replace spaces and underscores with hyphens
2301→+	s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
2302→+	// Remove anything that's not alphanumeric, hyphen, or slash
2303→+	var b strings.Builder
2304→+	prevHyphen := false
2305→+	for _, r := range s {
2306→+		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
2307→+			b.WriteRune(r)
2308→+			prevHyphen = false
2309→+		} else if r == '-' && !prevHyphen {
2310→+			b.WriteRune('-')
2311→+			prevHyphen = true
2312→+		}
2313→+	}
2314→+	return strings.Trim(b.String(), "-")
2315→+}
