2317→+// branchNeedsCreation checks if a branch exists locally.
2318→+func branchNeedsCreation(repo *git.Repository, branchName string) bool {
2319→+	_, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
2320→+	return err != nil
2321→+}
2322→+
2323→+// createBranch creates a new local branch pointing at HEAD without checking it out.
2324→+func createBranch(repo *git.Repository, branchName string) error {
2325→+	head, err := repo.Head()
2326→+	if err != nil {
2327→+		return fmt.Errorf("failed to get HEAD: %w", err)
2328→+	}
2329→+	ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), head.Hash())
2330→+	if err := repo.Storer.SetReference(ref); err != nil {
2331→+		return fmt.Errorf("failed to create branch ref: %w", err)
2332→+	}
2333→+	return nil
2334→+}
2335→+
2336→+// pushBranchToOrigin pushes a branch to the origin remote.
2337→+func pushBranchToOrigin(branchName string) error {
2338→+	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
2339→+	defer cancel()
2340→+	cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", "-u", "origin", branchName)
2341→+	if output, err := cmd.CombinedOutput(); err != nil {
2342→+		return fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
2343→+	}
2344→+	return nil
2345→+}
