107→func runTrailListAll(w io.Writer, statusFilter string, jsonOutput bool) error {
108→	// Fetch remote trails branch so we see trails from collaborators
109→	fetchTrailsBranch()
110→
111→	repo, err := strategy.OpenRepository(context.Background())
112→	if err != nil {
113→		return fmt.Errorf("failed to open repository: %w", err)
114→	}
115→
116→	store := trail.NewStore(repo)
117→	trails, err := store.List()
118→	if err != nil {
119→		return fmt.Errorf("failed to list trails: %w", err)
120→	}
121→
122→	if trails == nil {
123→		trails = []*trail.Metadata{}
124→	}
125→
126→	// Apply status filter
127→	if statusFilter != "" {
128→		status := trail.Status(statusFilter)
129→		if !status.IsValid() {
130→			return fmt.Errorf("invalid status %q: valid values are %s", statusFilter, formatValidStatuses())
131→		}
132→		var filtered []*trail.Metadata
133→		for _, t := range trails {
134→			if t.Status == status {
135→				filtered = append(filtered, t)
136→			}
137→		}
138→		trails = filtered
139→	}
140→
141→	// Sort by updated_at descending
142→	sort.Slice(trails, func(i, j int) bool {
143→		return trails[i].UpdatedAt.After(trails[j].UpdatedAt)
144→	})
145→
146→	if jsonOutput {
147→		enc := json.NewEncoder(w)
148→		enc.SetIndent("", "  ")
149→		if err := enc.Encode(trails); err != nil {
150→			return fmt.Errorf("failed to encode JSON: %w", err)
151→		}
152→		return nil
153→	}
154→
155→	if len(trails) == 0 {
156→		fmt.Fprintln(w, "No trails found.")
157→		fmt.Fprintln(w)
158→		fmt.Fprintln(w, "Commands:")
159→		fmt.Fprintln(w, "  entire trail create   Create a trail for the current branch")
160→		fmt.Fprintln(w, "  entire trail list     List all trails")
161→		fmt.Fprintln(w, "  entire trail update   Update trail metadata")
162→		return nil
163→	}
164→
165→	// Table output
166→	fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n", "BRANCH", "TITLE", "STATUS", "AUTHOR", "UPDATED")
167→	for _, t := range trails {
168→		branch := truncate(t.Branch, 30)
169→		title := truncate(t.Title, 40)
170→		fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n",
171→			branch, title, t.Status, truncate(t.Author, 15), timeAgo(t.UpdatedAt))
172→	}
173→
174→	return nil
175→}
