199→//nolint:cyclop // sequential steps for creating a trail — splitting would obscure the flow
200→func runTrailCreate(w, errW io.Writer, title, body, base, branch, statusStr string, checkout bool) error {
201→	repo, err := strategy.OpenRepository(context.Background())
202→	if err != nil {
203→		return fmt.Errorf("failed to open repository: %w", err)
204→	}
205→
206→	// Determine base branch
207→	if base == "" {
208→		base = strategy.GetDefaultBranchName(repo)
209→		if base == "" {
210→			base = defaultBaseBranch
211→		}
212→	}
213→
214→	_, currentBranch, _ := IsOnDefaultBranch(context.Background()) //nolint:errcheck // best-effort detection
215→	interactive := !hasFlag("title") && !hasFlag("branch")
216→
217→	if interactive {
218→		// Interactive flow: title → body → branch (derived) → status
219→		if err := runTrailCreateInteractive(&title, &body, &branch, &statusStr); err != nil {
220→			return err
221→		}
222→	} else {
223→		// Non-interactive: derive missing values from provided flags
224→		if branch == "" {
225→			if hasFlag("title") {
226→				branch = slugifyTitle(title)
227→			} else {
228→				branch = currentBranch
229→			}
230→		}
231→		if title == "" {
232→			title = trail.HumanizeBranchName(branch)
233→		}
234→	}
235→	if branch == "" {
236→		return errors.New("branch name is required")
237→	}
238→
239→	// Create the branch if it doesn't exist
240→	needsCreation := branchNeedsCreation(repo, branch)
241→	if needsCreation {
242→		if err := createBranch(repo, branch); err != nil {
243→			return fmt.Errorf("failed to create branch %q: %w", branch, err)
244→		}
245→		fmt.Fprintf(w, "Created branch %s\n", branch)
246→	} else if currentBranch != branch {
247→		fmt.Fprintf(errW, "Note: trail will be created for branch %q (not the current branch)\n", branch)
248→	}
249→
250→	// Check if trail already exists for this branch
251→	store := trail.NewStore(repo)
252→	existing, err := store.FindByBranch(branch)
253→	if err == nil && existing != nil {
254→		fmt.Fprintf(w, "Trail already exists for branch %q (ID: %s)\n", branch, existing.TrailID)
255→		return nil
256→	}
257→
258→	// Determine status
259→	var trailStatus trail.Status
260→	if statusStr != "" {
261→		trailStatus = trail.Status(statusStr)
262→		if !trailStatus.IsValid() {
263→			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
264→		}
265→	} else {
266→		trailStatus = trail.StatusDraft
267→	}
268→
269→	// Generate trail ID
270→	trailID, err := trail.GenerateID()
271→	if err != nil {
272→		return fmt.Errorf("failed to generate trail ID: %w", err)
273→	}
274→
275→	// Get author (GitHub username, falls back to git user.name)
276→	authorName := getTrailAuthor(repo)
277→
278→	now := time.Now()
279→	metadata := &trail.Metadata{
280→		TrailID:   trailID,
281→		Branch:    branch,
282→		Base:      base,
283→		Title:     title,
284→		Body:      body,
285→		Status:    trailStatus,
286→		Author:    authorName,
287→		Assignees: []string{},
288→		Labels:    []string{},
289→		CreatedAt: now,
290→		UpdatedAt: now,
291→	}
292→
293→	if err := store.Write(metadata, nil, nil); err != nil {
294→		return fmt.Errorf("failed to create trail: %w", err)
295→	}
296→
297→	fmt.Fprintf(w, "Created trail %q for branch %s (ID: %s)\n", title, branch, trailID)
298→
299→	// Push the branch and trail data to origin
300→	if needsCreation {
301→		if err := pushBranchToOrigin(branch); err != nil {
302→			fmt.Fprintf(errW, "Warning: failed to push branch: %v\n", err)
303→		} else {
304→			fmt.Fprintf(w, "Pushed branch %s to origin\n", branch)
305→		}
306→	}
307→	if err := strategy.PushTrailsBranch(context.Background(), "origin"); err != nil {
308→		fmt.Fprintf(errW, "Warning: failed to push trail data: %v\n", err)
309→	}
310→
311→	// Checkout the branch if requested or prompted
312→	if needsCreation && currentBranch != branch {
313→		shouldCheckout := checkout
314→		if !shouldCheckout && !hasFlag("checkout") {
315→			// Interactive: ask whether to checkout
316→			form := NewAccessibleForm(
317→				huh.NewGroup(
318→					huh.NewConfirm().
319→						Title(fmt.Sprintf("Check out branch %s?", branch)).
320→						Value(&shouldCheckout),
321→				),
322→			)
323→			if formErr := form.Run(); formErr == nil && shouldCheckout {
324→				checkout = true
325→			}
326→		}
327→		if checkout {
328→			if err := CheckoutBranch(context.Background(), branch); err != nil {
329→				return fmt.Errorf("failed to checkout branch %q: %w", branch, err)
330→			}
331→			fmt.Fprintf(w, "Switched to branch %s\n", branch)
332→		}
333→	}
334→
335→	return nil
336→}
