360→func runTrailUpdate(w io.Writer, statusStr, title, body, branch string, labelAdd, labelRemove []string) error {
361→	repo, err := strategy.OpenRepository(context.Background())
362→	if err != nil {
363→		return fmt.Errorf("failed to open repository: %w", err)
364→	}
365→
366→	// Determine branch
367→	if branch == "" {
368→		branch, err = GetCurrentBranch(context.Background())
369→		if err != nil {
370→			return fmt.Errorf("failed to determine current branch: %w", err)
371→		}
372→	}
373→
374→	store := trail.NewStore(repo)
375→	metadata, err := store.FindByBranch(branch)
376→	if err != nil {
377→		return fmt.Errorf("failed to find trail: %w", err)
378→	}
379→	if metadata == nil {
380→		return fmt.Errorf("no trail found for branch %q", branch)
381→	}
382→
383→	// Interactive mode when no flags are provided
384→	noFlags := statusStr == "" && title == "" && body == "" && labelAdd == nil && labelRemove == nil
385→	if noFlags {
386→		// Build status options with current value as default.
387→		// Exclude "done" and "closed" unless the trail is already in that status
388→		// (otherwise the select would silently reset to the first option).
389→		var statusOptions []huh.Option[string]
390→		for _, s := range trail.ValidStatuses() {
391→			if (s == trail.StatusDone || s == trail.StatusClosed) && s != metadata.Status {
392→				continue
393→			}
394→			label := string(s)
395→			if s == metadata.Status {
396→				label += " (current)"
397→			}
398→			statusOptions = append(statusOptions, huh.NewOption(label, string(s)))
399→		}
400→		statusStr = string(metadata.Status)
401→		title = metadata.Title
402→		body = metadata.Body
403→
404→		form := NewAccessibleForm(
405→			huh.NewGroup(
406→				huh.NewSelect[string]().
407→					Title("Status").
408→					Options(statusOptions...).
409→					Value(&statusStr),
410→				huh.NewInput().
411→					Title("Title").
412→					Value(&title),
413→				huh.NewText().
414→					Title("Body").
415→					Value(&body),
416→			),
417→		)
418→		if formErr := form.Run(); formErr != nil {
419→			return fmt.Errorf("form cancelled: %w", formErr)
420→		}
421→	}
422→
423→	// Validate status if provided
424→	if statusStr != "" {
425→		status := trail.Status(statusStr)
426→		if !status.IsValid() {
427→			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
428→		}
429→	}
430→
431→	err = store.Update(metadata.TrailID, func(m *trail.Metadata) {
432→		if statusStr != "" {
433→			m.Status = trail.Status(statusStr)
434→		}
435→		if title != "" {
436→			m.Title = title
437→		}
438→		if body != "" {
439→			m.Body = body
440→		}
441→		for _, l := range labelAdd {
442→			if !containsString(m.Labels, l) {
443→				m.Labels = append(m.Labels, l)
444→			}
445→		}
446→		for _, l := range labelRemove {
447→			m.Labels = removeString(m.Labels, l)
448→		}
449→	})
450→	if err != nil {
451→		return fmt.Errorf("failed to update trail: %w", err)
452→	}
453→
454→	fmt.Fprintf(w, "Updated trail for branch %s\n", branch)
455→	return nil
456→}
