601→// slugifyTitle converts a title string into a branch-friendly slug.
602→// Example: "Add user authentication" -> "add-user-authentication"
603→func slugifyTitle(title string) string {
604→	s := strings.ToLower(strings.TrimSpace(title))
605→	// Replace spaces and underscores with hyphens
606→	s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
607→	// Remove anything that's not alphanumeric, hyphen, or slash
608→	var b strings.Builder
609→	prevHyphen := false
610→	for _, r := range s {
611→		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
612→			b.WriteRune(r)
613→			prevHyphen = false
614→		} else if r == '-' && !prevHyphen {
615→			b.WriteRune('-')
616→			prevHyphen = true
617→		}
618→	}
619→	return strings.Trim(b.String(), "-")
620→}
